(function() {
  'use strict';

  const sliderPf = document.getElementById('slider-pf');
  const sliderFi = document.getElementById('slider-fi');
  const sliderNi = document.getElementById('slider-ni');
  const valPf = document.getElementById('val-pf');
  const valFi = document.getElementById('val-fi');
  const valNi = document.getElementById('val-ni');
  const resNumerator = document.getElementById('res-numerator');
  const resDenominator = document.getElementById('res-denominator');
  const resFsim = document.getElementById('res-fsim');
  const credenceValue = document.getElementById('credence-value');
  const resetBtn = document.getElementById('reset-formalism');

  if (!sliderPf || !sliderFi || !sliderNi) return;

  function getNiValue() {
    const base = 10;
    const exp = parseFloat(sliderNi.value);
    return Math.pow(base, exp);
  }

  function formatNumber(num) {
    if (num >= 1e6) {
      return num.toExponential(2);
    }
    return num.toLocaleString('en-US', { maximumFractionDigits: 4 });
  }

  function updateCalculation() {
    const pf = parseFloat(sliderPf.value);
    const fi = parseFloat(sliderFi.value);
    const ni = getNiValue();

    valPf.textContent = pf.toFixed(2);
    valFi.textContent = fi.toFixed(2);

    const niDisplay = ni >= 1e6 ? `10^${Math.log10(ni)}` : ni.toFixed(0);
    valNi.textContent = niDisplay;

    const numerator = pf * fi * ni;
    const denominator = numerator + 1;
    const fsim = denominator === 0 ? 0 : numerator / denominator;

    resNumerator.textContent = formatNumber(numerator);
    resDenominator.textContent = formatNumber(denominator);
    resFsim.textContent = fsim.toFixed(4);

    if (credenceValue) {
      credenceValue.textContent = fsim.toFixed(4);
    }
  }

  function resetControls() {
    sliderPf.value = 0.2;
    sliderFi.value = 0.5;
    sliderNi.value = 3;
    updateCalculation();
  }

  sliderPf.addEventListener('input', updateCalculation);
  sliderFi.addEventListener('input', updateCalculation);
  sliderNi.addEventListener('input', updateCalculation);

  if (resetBtn) {
    resetBtn.addEventListener('click', resetControls);
  }

  updateCalculation();

  const sourceBtns = document.querySelectorAll('.source-btn');
  sourceBtns.forEach(btn => {
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      const sourceId = this.getAttribute('data-source');
      if (window.paperMindData && window.paperMindData.sources && sourceId) {
        console.log('Source requested:', sourceId);
      }
    });
  });
})();
